<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {Heart,Plus,ArrowLeft,Search,ArrowUpRight} from 'lucide-vue-next'
import {useRouter,useRoute,onBeforeRouteLeave} from 'vue-router'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import type {CharacterCard} from '../tavern/card-format'
import {cardAvatar} from '../tavern/card-container'
import CharacterPortrait from '../presentation/CharacterPortrait.vue'
import {styles,type CompanionProfile} from './contract'
import {newCompanionCreation,readyCompanionCreation,saveCompanionCreation,createDraftCompanion,validateCompanionCreation,type CompanionCreationDraft} from './creation'
import PromotionPanel from './PromotionPanel.vue'
import type {PromotionTarget} from './promotion'
const route=useRoute(),store=useLocal(),router=useRouter(),items=ref<Document<CompanionProfile>[]>([]),cards=ref<Document<CharacterCard>[]>([]),drafts=ref<Document<CompanionCreationDraft>[]>([]),draft=ref<Document<CompanionCreationDraft>|null>(null),name=ref(''),personality=ref(''),style=ref<CompanionProfile['style']>('gentle'),source=ref(''),sourceRevision=ref<number|null>(null),creating=ref(false),error=ref(''),busy=ref(false),loading=ref(true),conflict=ref(false),saved=ref(false),sourceChanged=ref(false)
const search=ref(''),avatars=ref<Record<string,string>>({}),portraitLifecycle=new AbortController()
const visibleProfiles=computed(()=>items.value.filter(row=>(row.value.name+' '+row.value.personality).toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase())))
const promotionTarget=ref<PromotionTarget|null>(null),promotionInitial=ref<Pick<CompanionProfile,'name'|'personality'|'style'>>({name:'',personality:'',style:'gentle'})
const fields=()=>({name:name.value,personality:personality.value,style:style.value,sourceCard:source.value?{id:source.value,revision:sourceRevision.value!}:null})
const editing=computed(()=>draft.value?.value.status==='editing'),dirty=computed(()=>!!draft.value&&editing.value&&canonical(fields())!==canonical({name:draft.value.value.name,personality:draft.value.value.personality,style:draft.value.value.style,sourceCard:draft.value.value.sourceCard}))
let disposed=false,initializing=true,createdReturn=false,loadEpoch=0,timer:ReturnType<typeof setTimeout>|null=null,work=Promise.resolve(),opening:ReturnType<typeof newCompanionCreation>|null=null
async function load(){const vault=store.vault,ticket=++loadEpoch;if(!vault)return;const [profiles,roles,pending]=await Promise.all([vault.list<CompanionProfile>('companion'),vault.list<CharacterCard>('card'),vault.listPrefix<CompanionCreationDraft>('companion-draft:')]);if(disposed||ticket!==loadEpoch||store.vault!==vault||!vault.unlocked)return;items.value=profiles.filter(row=>!row.value.deleted);cards.value=roles;drafts.value=pending.filter(row=>['editing','ready'].includes(row.value.status));const portraits=await Promise.all(items.value.map(async row=>{const ref=row.value.sourceCard;if(!ref)return [row.id,null] as const;try{const source=await vault.read<CharacterCard>(ref.id,ref.revision);return [row.id,source?.kind==='card'?await cardAvatar(vault,source,portraitLifecycle.signal):null] as const}catch{return [row.id,null] as const}}));if(disposed||ticket!==loadEpoch||store.vault!==vault||!vault.unlocked){for(const [,url] of portraits)if(url)URL.revokeObjectURL(url);return}for(const url of Object.values(avatars.value))URL.revokeObjectURL(url);avatars.value=Object.fromEntries(portraits.filter((entry):entry is readonly [string,string]=>!!entry[1]))}
function show(row:Document<CompanionCreationDraft>){draft.value=row;name.value=row.value.name;personality.value=row.value.personality;style.value=row.value.style;source.value=row.value.sourceCard?.id||'';sourceRevision.value=row.value.sourceCard?.revision||null;saved.value=true}
function choose(){sourceChanged.value=false;const row=cards.value.find(card=>card.id===source.value);sourceRevision.value=row?.revision||null;if(row){name.value=row.value.name;personality.value=row.value.personality||row.value.description}}
async function persist(){
 if(timer){clearTimeout(timer);timer=null}const vault=store.vault,values=fields();if(!vault||!draft.value||!editing.value||conflict.value||disposed)return;saved.value=false
 work=work.catch(()=>{}).then(async()=>{const current=draft.value;if(!current||current.value.status!=='editing'||disposed||store.vault!==vault||!vault.unlocked||conflict.value)return;if(canonical({name:current.value.name,personality:current.value.personality,style:current.value.style,sourceCard:current.value.sourceCard})===canonical(values)){saved.value=!dirty.value;return}
  try{const next=await saveCompanionCreation(vault,current.id,current.revision,{...current.value,...values});if(!disposed&&store.vault===vault&&draft.value?.id===current.id){draft.value=next;saved.value=!dirty.value;error.value=''}}catch(e){if(!disposed&&store.vault===vault){error.value=(e as Error).message;conflict.value=(e as {code?:string}).code==='REVISION_CONFLICT'}}
 });await work
}
watch([name,personality,style,source,sourceRevision],()=>{if(initializing||!editing.value||disposed)return;saved.value=false;if(timer)clearTimeout(timer);timer=setTimeout(()=>void persist(),250)})
async function initialize(){
 const vault=store.vault;if(!vault||busy.value||disposed)return;busy.value=true;error.value=''
 try{await load();if(disposed||store.vault!==vault||!vault.unlocked)return
  if(typeof route.query.draft==='string'){const current=await vault.read<CompanionCreationDraft>(route.query.draft);if(!current||current.kind!=='settings')throw Error('这份伴侣草稿已不可用');validateCompanionCreation(current.value,current.id);if(current.value.status==='discarded')throw Error('这份伴侣草稿已结束');if(!disposed&&store.vault===vault){show(current);creating.value=true}}
  else if(route.query.create==='1'){opening??=newCompanionCreation();const initial=opening,prior=await vault.read<CompanionCreationDraft>(initial.id);if(prior){if(prior.kind!=='settings')throw Error('草稿身份已被占用');validateCompanionCreation(prior.value,prior.id)}const current=prior||await saveCompanionCreation(vault,initial.id,0,initial.value);if(!disposed&&store.vault===vault&&vault.unlocked)await router.replace({path:route.path,query:{...route.query,create:undefined,draft:current.id}})}
 }catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed){initializing=false;loading.value=false;busy.value=false}}
}
async function create(){
 const vault=store.vault;if(!vault||!draft.value||busy.value||conflict.value)return;busy.value=true;error.value=''
 try{await persist();await work;const current=draft.value;if(!current||dirty.value||conflict.value)throw Error('草稿尚未保存，请先重试保存')
  if(current.value.sourceCard){const latest=await vault.read<CharacterCard>(current.value.sourceCard.id);if(!latest||latest.kind!=='card')throw Error('这份来源角色已不可用，已填写的设定保留');if(latest.revision!==current.value.sourceCard.revision){sourceChanged.value=true;throw Error('来源角色已更新，请选择使用当前角色版本')}promotionInitial.value={name:name.value,personality:personality.value,style:style.value};promotionTarget.value={kind:'card',...current.value.sourceCard};return}
  if(current.value.status==='editing'){const ready=await saveCompanionCreation(vault,current.id,current.revision,readyCompanionCreation(current.value));if(disposed||store.vault!==vault||!vault.unlocked)return;draft.value=ready}
  const frozen=draft.value!,id=frozen.value.status==='completed'?frozen.value.companionId:await createDraftCompanion(vault,frozen)
  if(!disposed&&store.vault===vault&&vault.unlocked){createdReturn=true;busy.value=false;await router.push('/local/companions/'+id)}
 }catch(e){if(!disposed&&store.vault===vault){error.value=(e as Error).message;conflict.value=(e as {code?:string}).code==='REVISION_CONFLICT'}}finally{if(!disposed)busy.value=false}
}
async function updateSourceVersion(){
 const vault=store.vault,id=source.value;if(!vault||!id||busy.value||!editing.value)return;busy.value=true;error.value=''
 try{const latest=await vault.read<CharacterCard>(id);if(!latest||latest.kind!=='card')throw Error('这份来源角色已不可用');if(disposed||store.vault!==vault||!vault.unlocked)return;sourceRevision.value=latest.revision;await persist();await work;if(!dirty.value&&!conflict.value){sourceChanged.value=false;error.value=''}}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed)busy.value=false}
}
async function recheck(){const vault=store.vault,current=draft.value;if(!vault||!current||busy.value)return;busy.value=true;initializing=true;try{const latest=await vault.read<CompanionCreationDraft>(current.id);if(!latest||latest.kind!=='settings')throw Error('这份伴侣草稿已不可用');validateCompanionCreation(latest.value,latest.id);if(!disposed&&store.vault===vault){show(latest);conflict.value=false;error.value=''}}catch(e){if(!disposed)error.value=(e as Error).message}finally{initializing=false;busy.value=false}}
function start(){if(busy.value)return;void router.push(creating.value?'/local/companions':{path:'/local/companions',query:{create:'1'}})}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async to=>{if(createdReturn)return;if(busy.value&&(!loading.value||route.query.create||route.query.draft))return false;await persist();await work;if(dirty.value){error.value='草稿尚未保存，请重试保存后再离开';return false}const vault=store.vault,current=draft.value;if(current?.value.status==='ready')return false
 if(vault&&current?.value.sourceCard&&to.path.startsWith('/local/companions/')){const id=decodeURIComponent(to.path.slice('/local/companions/'.length)),target=await vault.read<CompanionProfile>(id);if(target?.kind==='companion'&&target.value.sourceCard?.id===current.value.sourceCard.id&&target.value.sourceCard.revision===current.value.sourceCard.revision){try{await saveCompanionCreation(vault,current.id,current.revision,{...current.value,status:'discarded'})}catch(e){error.value=(e as Error).message;return false}}}
})
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);void initialize()});onUnmounted(()=>{disposed=true;portraitLifecycle.abort();for(const url of Object.values(avatars.value))URL.revokeObjectURL(url);window.removeEventListener('beforeunload',beforeUnload);if(timer)clearTimeout(timer)})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">COMPANIONS</span><h1>伴侣</h1></div><button class="final-primary" :disabled="loading||busy" @click="start"><Plus v-if="!creating" :size="18"/><ArrowLeft v-else :size="18"/>{{creating?'收起':'创建'}}</button></div><p v-if="loading" role="status">正在打开…</p><p v-if="error" class="final-error" role="alert">{{error}}</p><button v-if="!draft&&!loading&&route.query.create" :disabled="busy" @click="initialize">重试打开草稿</button><button v-if="sourceChanged" :disabled="busy||!editing||conflict" @click="updateSourceVersion">使用当前角色版本</button><form v-if="creating&&draft" class="final-card-form" @submit.prevent="create"><fieldset :disabled="busy||!editing"><label v-if="cards.length">从角色开始<select v-model="source" aria-label="从角色开始" @change="choose"><option value="">独立创建</option><option v-for="card in cards" :key="card.id" :value="card.id">{{card.value.name}}</option></select></label><label>名字<input v-model="name" required maxlength="200"></label><label>想认识怎样的 TA<textarea v-model="personality" maxlength="20000"></textarea></label><label>相处风格<select v-model="style" aria-label="相处风格"><option v-for="(label,key) in styles" :key="key" :value="key">{{label}}</option></select></label></fieldset><div class="companion-draft-status"><span class="final-subtle" role="status">{{editing?(saved&&!dirty?'草稿已保存':'正在保存草稿…'):draft.value.status==='completed'?'伴侣已保存':'设定已保存'}}</span><button v-if="dirty&&!conflict" type="button" :disabled="busy" @click="persist">重试保存草稿</button></div><button v-if="conflict" type="button" :disabled="busy" @click="recheck">载入当前伴侣草稿</button><button v-else class="final-primary" :disabled="busy">{{busy?'正在保存…':draft.value.status==='ready'?'重试创建伴侣':draft.value.status==='completed'?'打开伴侣':'保存'}}</button></form><template v-else-if="!loading"><div v-if="drafts.length" class="companion-drafts"><RouterLink v-for="row in drafts" :key="row.id" :to="{path:'/local/companions',query:{draft:row.id}}"><Heart :size="18"/>{{row.value.name||'未命名的伴侣'}}<small>{{row.value.status==='ready'?'继续保存':'草稿'}}</small></RouterLink></div><div v-if="!items.length" class="final-empty"><Heart :size="40"/><h2>认识一个与你相伴的人</h2><button class="final-primary" @click="start">创建伴侣</button></div><template v-else><label class="companion-search"><Search :size="18"/><input v-model="search" type="search" aria-label="搜索伴侣" placeholder="寻找与你相伴的人" maxlength="200"></label><div v-if="!visibleProfiles.length" class="final-empty"><Search :size="32"/><h2>没有找到 TA</h2><button @click="search=''">清除搜索</button></div><div v-else class="companion-grid"><RouterLink v-for="item in visibleProfiles" :key="item.id" :to="'/local/companions/'+item.id" class="companion-card"><CharacterPortrait :name="item.value.name" :src="avatars[item.id]"/><div class="companion-card-heading"><h2 :title="item.value.name">{{item.value.name}}</h2><ArrowUpRight :size="18"/></div><p>{{item.value.personality.slice(0,120)}}</p><span class="final-subtle">{{new Date(item.value.createdAt).toLocaleDateString()}} · 相识</span></RouterLink></div></template></template><PromotionPanel v-if="promotionTarget" :target="promotionTarget" :initial="promotionInitial" @close="promotionTarget=null"/></section></template>
<style scoped>.companion-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:28px 24px}.companion-card{display:grid;gap:10px;align-content:start;min-width:0}.companion-card-heading{display:flex;align-items:center;justify-content:space-between;gap:8px}.companion-card-heading h2{font-size:21px;overflow-wrap:anywhere;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:3em}.companion-card-heading svg{flex:none;color:var(--quiet)}.companion-card p{color:var(--quiet);font-size:14px;line-height:1.7;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:2.8em}.companion-search{position:relative;max-width:560px;margin:0 0 28px}.companion-search svg{position:absolute;left:14px;top:16px;color:var(--quiet)}.companion-search input{padding-left:44px}@media(max-width:600px){.companion-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px 16px}.companion-card-heading h2{font-size:19px}}.final-card-form fieldset{display:grid;gap:20px;margin:0;padding:0;border:0;min-width:0}.companion-draft-status{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.companion-drafts{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:24px}.companion-drafts>a{display:flex;align-items:center;gap:10px;min-height:48px;max-width:100%;padding:12px 16px;border:1px solid var(--edge);border-radius:12px;overflow-wrap:anywhere}.companion-drafts small{color:var(--quiet);white-space:nowrap}</style>
